cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <cuda_pipeline.h>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define PIPE_ASYNC_COPY(dst, src) __pipeline_memcpy_async((dst), (src), 16)
#define PIPE_COMMIT() __pipeline_commit()
#define PIPE_WAIT_ONE() __pipeline_wait_prior(1)
#else
#define PIPE_ASYNC_COPY(dst, src) *reinterpret_cast<uint4*>(dst) = *reinterpret_cast<const uint4*>(src)
#define PIPE_COMMIT()
#define PIPE_WAIT_ONE()
#endif
#define BATCH_SIZE 2
#define NUM_HEADS 32
#define SEQ_LEN 256
#define HEAD_DIM 1024
#define THREADS 256
#define TILE_M 64
#define TILE_N 64
#define TILE_K 64
#define PIPE_K 32
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16
#define WARPS_M 4
#define WARPS_N 2
#define FRAGS_N (TILE_N / (WARPS_N * WMMA_N))
__global__ void qk_scores_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    float* __restrict__ S
) {
    __shared__ __align__(16) __half q_sh[2][TILE_M][PIPE_K];
    __shared__ __align__(16) __half k_sh[2][TILE_N][PIPE_K];
    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int warp_m = warp_id % WARPS_M;
    const int warp_n = warp_id / WARPS_M;
    const int bh = blockIdx.z;
    const int m0 = blockIdx.y * TILE_M;
    const int n0 = blockIdx.x * TILE_N;
    const size_t base = (size_t)bh * SEQ_LEN * HEAD_DIM;
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag[FRAGS_N];
    for (int f = 0; f < FRAGS_N; ++f)
        nvcuda::wmma::fill_fragment(acc_frag[f], 0.0f);
    auto load_stage = [&](int buf, int k0) {
        for (int idx = tid; idx < (TILE_M * PIPE_K) / 8; idx += THREADS) {
            const int r = idx / (PIPE_K / 8);
            const int c8 = (idx % (PIPE_K / 8)) * 8;
            PIPE_ASYNC_COPY(&q_sh[buf][r][c8], Q + base + (size_t)(m0 + r) * HEAD_DIM + k0 + c8);
            PIPE_ASYNC_COPY(&k_sh[buf][r][c8], K + base + (size_t)(n0 + r) * HEAD_DIM + k0 + c8);
        }
    };
    load_stage(0, 0);
    PIPE_COMMIT();
    int buf = 0;
    for (int k0 = 0; k0 < HEAD_DIM; k0 += PIPE_K) {
        const int nxt = buf ^ 1;
        if (k0 + PIPE_K < HEAD_DIM) {
            load_stage(nxt, k0 + PIPE_K);
        }
        PIPE_COMMIT();
        PIPE_WAIT_ONE();
        __syncthreads();
        for (int kk = 0; kk < PIPE_K; kk += WMMA_K) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> a_frag;
            nvcuda::wmma::load_matrix_sync(a_frag, &q_sh[buf][warp_m * WMMA_M][kk], PIPE_K);
            for (int f = 0; f < FRAGS_N; ++f) {
                const int wn = warp_n * (WMMA_N * FRAGS_N) + f * WMMA_N;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::col_major> b_frag;
                nvcuda::wmma::load_matrix_sync(b_frag, &k_sh[buf][wn][kk], PIPE_K);
                nvcuda::wmma::mma_sync(acc_frag[f], a_frag, b_frag, acc_frag[f]);
            }
        }
        buf = nxt;
        __syncthreads();
    }
    for (int f = 0; f < FRAGS_N; ++f) {
        float* out = S + ((size_t)bh * SEQ_LEN + m0 + warp_m * WMMA_M) * SEQ_LEN + n0 + warp_n * (WMMA_N * FRAGS_N) + f * WMMA_N;
        nvcuda::wmma::store_matrix_sync(out, acc_frag[f], SEQ_LEN, nvcuda::wmma::mem_row_major);
    }
}
__global__ void softmax_rows_kernel(
    const float* __restrict__ S,
    __half* __restrict__ P
) {
    __shared__ float row[SEQ_LEN];
    __shared__ float red[THREADS];
    __shared__ float m_sh;
    __shared__ float sum_sh;
    const int tid = threadIdx.x;
    const int bh = blockIdx.x;
    const int r = blockIdx.y;
    const size_t base = ((size_t)bh * SEQ_LEN + r) * SEQ_LEN;
    const float scale = rsqrtf((float)HEAD_DIM);
    const float x = S[base + tid] * scale;
    row[tid] = x;
    red[tid] = x;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) red[tid] = fmaxf(red[tid], red[tid + offset]);
        __syncthreads();
    }
    if (tid == 0) m_sh = red[0];
    __syncthreads();
    const float e = expf(row[tid] - m_sh);
    row[tid] = e;
    red[tid] = e;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) red[tid] += red[tid + offset];
        __syncthreads();
    }
    if (tid == 0) sum_sh = red[0];
    __syncthreads();
    P[base + tid] = __float2half(row[tid] / sum_sh);
}
__global__ void pv_output_kernel(
    const __half* __restrict__ P,
    const __half* __restrict__ V,
    __half* __restrict__ O
) {
    __shared__ __align__(16) __half p_sh[2][TILE_M][PIPE_K];
    __shared__ __align__(16) __half v_sh[2][PIPE_K][TILE_N];
    __shared__ __align__(16) float c_sh[TILE_M][TILE_N];
    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int warp_m = warp_id % WARPS_M;
    const int warp_n = warp_id / WARPS_M;
    const int bh = blockIdx.z;
    const int m0 = blockIdx.y * TILE_M;
    const int n0 = blockIdx.x * TILE_N;
    const size_t base = (size_t)bh * SEQ_LEN * HEAD_DIM;
    const size_t p_base = (size_t)bh * SEQ_LEN * SEQ_LEN;
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag[FRAGS_N];
    for (int f = 0; f < FRAGS_N; ++f)
        nvcuda::wmma::fill_fragment(acc_frag[f], 0.0f);
    auto load_stage = [&](int buf, int k0) {
        for (int idx = tid; idx < (TILE_M * PIPE_K) / 8; idx += THREADS) {
            const int r = idx / (PIPE_K / 8);
            const int c8 = (idx % (PIPE_K / 8)) * 8;
            PIPE_ASYNC_COPY(&p_sh[buf][r][c8], P + p_base + (size_t)(m0 + r) * SEQ_LEN + k0 + c8);
        }
        for (int idx = tid; idx < (PIPE_K * TILE_N) / 8; idx += THREADS) {
            const int r = idx / (TILE_N / 8);
            const int c8 = (idx % (TILE_N / 8)) * 8;
            PIPE_ASYNC_COPY(&v_sh[buf][r][c8], V + base + (size_t)(k0 + r) * HEAD_DIM + n0 + c8);
        }
    };
    load_stage(0, 0);
    PIPE_COMMIT();
    int buf = 0;
    for (int k0 = 0; k0 < SEQ_LEN; k0 += PIPE_K) {
        const int nxt = buf ^ 1;
        if (k0 + PIPE_K < SEQ_LEN) {
            load_stage(nxt, k0 + PIPE_K);
        }
        PIPE_COMMIT();
        PIPE_WAIT_ONE();
        __syncthreads();
        for (int kk = 0; kk < PIPE_K; kk += WMMA_K) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> a_frag;
            nvcuda::wmma::load_matrix_sync(a_frag, &p_sh[buf][warp_m * WMMA_M][kk], PIPE_K);
            for (int f = 0; f < FRAGS_N; ++f) {
                const int wn = warp_n * (WMMA_N * FRAGS_N) + f * WMMA_N;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> b_frag;
                nvcuda::wmma::load_matrix_sync(b_frag, &v_sh[buf][kk][wn], TILE_N);
                nvcuda::wmma::mma_sync(acc_frag[f], a_frag, b_frag, acc_frag[f]);
            }
        }
        buf = nxt;
        __syncthreads();
    }
    for (int f = 0; f < FRAGS_N; ++f) {
        const int wn = warp_n * (WMMA_N * FRAGS_N) + f * WMMA_N;
        nvcuda::wmma::store_matrix_sync(&c_sh[warp_m * WMMA_M][wn], acc_frag[f], TILE_N, nvcuda::wmma::mem_row_major);
    }
    __syncthreads();
    for (int idx = tid; idx < TILE_M * TILE_N; idx += THREADS) {
        const int r = idx / TILE_N;
        const int c = idx % TILE_N;
        O[base + (size_t)(m0 + r) * HEAD_DIM + n0 + c] = __float2half(c_sh[r][c]);
    }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have identical shapes");
    TORCH_CHECK(Q.size(0) == BATCH_SIZE && Q.size(1) == NUM_HEADS &&
                Q.size(2) == SEQ_LEN && Q.size(3) == HEAD_DIM,
                "Expected shape (2, 32, 256, 1024)");

    auto q = Q.contiguous();
    auto k = K.contiguous();
    auto v = V.contiguous();
    auto out = at::empty_like(q);
    auto s_ws = at::empty({BATCH_SIZE * NUM_HEADS, SEQ_LEN, SEQ_LEN}, q.options().dtype(at::kFloat));
    auto p_ws = at::empty({BATCH_SIZE * NUM_HEADS, SEQ_LEN, SEQ_LEN}, q.options());
    const int bh = BATCH_SIZE * NUM_HEADS;
    dim3 block(THREADS);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    dim3 qk_grid(SEQ_LEN / TILE_N, SEQ_LEN / TILE_M, bh);
    qk_scores_kernel<<<qk_grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(q.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(k.data_ptr<at::Half>()),
        s_ws.data_ptr<float>()
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    dim3 sm_grid(bh, SEQ_LEN);
    softmax_rows_kernel<<<sm_grid, block, 0, stream>>>(
        s_ws.data_ptr<float>(),
        reinterpret_cast<__half*>(p_ws.data_ptr<at::Half>())
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    dim3 pv_grid(HEAD_DIM / TILE_N, SEQ_LEN / TILE_M, bh);
    pv_output_kernel<<<pv_grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(p_ws.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(v.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(out.data_ptr<at::Half>())
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
