        const int wn = warp_n * (WMMA_N * FRAGS_N) + f * WMMA_N;
        nvcuda::wmma::store_matrix_sync(&c_sh[warp_m * WMMA_M][wn], acc_frag[f], TILE_N, nvcuda::wmma::mem_row_major);
    }
    __syncthreads();
    for (int idx = tid; idx < TILE_M * TILE_N; idx += THREADS) {
        const int r = idx / TILE_N;
        const int c = idx % TILE_N;
        O[base + (size_t)(m0 + r) * HEAD_DIM + n0 + c] = __float2half(c_sh[r][c]);
    }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have identical shapes");
    TORCH_CHECK(Q.size(0) == BATCH_SIZE && Q.size(1) == NUM_HEADS &&
                Q.size(2) == SEQ_LEN && Q.size(3) == HEAD_DIM,
                "Expected shape (2, 32, 256, 1024)");

    auto q = Q.contiguous();
    auto k = K.contiguous();
    auto v = V.contiguous();
    auto out = at::empty_like(q);
    auto s_ws = at::empty({BATCH_SIZE * NUM_HEADS, SEQ_LEN, SEQ_LEN}, q.options().dtype(at::kFloat));
    auto p_ws = at::empty({BATCH_SIZE * NUM_HEADS, SEQ_LEN, SEQ_LEN}, q.options());
    const int bh = BATCH_SIZE * NUM_HEADS;
    dim3 block(THREADS);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    dim3 qk_grid(SEQ_LEN / TILE_N, SEQ_LEN / TILE_M, bh);
    qk_scores_kernel<<<qk_grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(q.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(k.data_ptr<at::Half>()),
        s_ws.data_ptr<float>()
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    dim3 sm_grid(bh, SEQ_LEN);
    softmax_rows_kernel<<<sm_grid, block, 0, stream>>>(
        s_ws.data_ptr<float>(),
        reinterpret_cast<__half*>(p_ws.data_ptr<at::Half>())
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    dim3 pv_grid(HEAD_DIM / TILE_N, SEQ_LEN / TILE_M, bh);
    pv_output_kernel<<<pv_grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(p_ws.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(v.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(out.data_ptr<at::Half>())
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
